import React, { useState } from 'react';
import './WelcomeCards.css'; // Import CSS for styling

// Import images
import image1 from '../images/image1.jpg';
import image2 from '../images/image2.jpg';
import image3 from '../images/image3.jpg';
import image4 from '../images/image4.jpg';
import image5 from '../images/image5.jpg';
import image6 from '../images/image6.jpg';
import image7 from '../images/image7.jpg';
import image8 from '../images/image8.jpg';
import image9 from '../images/image9.jpg';
import image10 from '../images/image10.jpg';
import image11 from '../images/image11.jpg';
import image12 from '../images/image12.jpg';
import image13 from '../images/image13.jpg';
import image14 from '../images/image14.jpg';
import image15 from '../images/image15.jpg';

const WelcomeCards = () => {
  const allCards = [
    { id: 1, title: 'Card Title 1', description: 'This is a description for card number 1.', imageUrl: image1 },
    { id: 2, title: 'Card Title 2', description: 'This is a description for card number 2.', imageUrl: image2 },
    { id: 3, title: 'Card Title 3', description: 'This is a description for card number 3.', imageUrl: image3 },
    { id: 4, title: 'Card Title 4', description: 'This is a description for card number 4.', imageUrl: image4 },
    { id: 5, title: 'Card Title 5', description: 'This is a description for card number 5.', imageUrl: image5 },
    { id: 6, title: 'Card Title 6', description: 'This is a description for card number 6.', imageUrl: image6 },
    { id: 7, title: 'Card Title 7', description: 'This is a description for card number 7.', imageUrl: image7 },
    { id: 8, title: 'Card Title 8', description: 'This is a description for card number 8.', imageUrl: image8 },
    { id: 9, title: 'Card Title 9', description: 'This is a description for card number 9.', imageUrl: image9 },
    { id: 10, title: 'Card Title 10', description: 'This is a description for card number 10.', imageUrl: image10 },
    { id: 11, title: 'Card Title 11', description: 'This is a description for card number 11.', imageUrl: image11 },
    { id: 12, title: 'Card Title 12', description: 'This is a description for card number 12.', imageUrl: image12 },
    { id: 13, title: 'Card Title 13', description: 'This is a description for card number 13.', imageUrl: image13 },
    { id: 14, title: 'Card Title 14', description: 'This is a description for card number 14.', imageUrl: image14 },
    { id: 15, title: 'Card Title 15', description: 'This is a description for card number 15.', imageUrl: image15 },
  ];

  const cardsPerPage = 9;
  const [currentPage, setCurrentPage] = useState(0);

  const startIndex = currentPage * cardsPerPage;
  const currentCards = allCards.slice(startIndex, startIndex + cardsPerPage);
  const totalPages = Math.ceil(allCards.length / cardsPerPage);

  const handleNext = () => {
    if (currentPage < totalPages - 1) {
      setCurrentPage(currentPage + 1);
    }
  };

  const handlePrevious = () => {
    if (currentPage > 0) {
      setCurrentPage(currentPage - 1);
    }
  };

  return (
    <div className="cards-container">
      {currentCards.map((card) => (
        <div key={card.id} className="card">
          <img src={card.imageUrl} alt={card.title} className="card-image" />
          <div className="card-content">
            <h3 className="card-title">{card.title}</h3>
            <p className="card-description">{card.description}</p>
          </div>
        </div>
      ))}
      <div className="pagination-controls">
        <button onClick={handlePrevious} disabled={currentPage === 0} className="pagination-button">
          Previous
        </button>
        <button onClick={handleNext} disabled={currentPage === totalPages - 1} className="pagination-button">
          Next
        </button>
      </div>
    </div>
  );
};

export default WelcomeCards;
